-- Expanded lessons and illustrated two-character sample conversations.
ALTER TABLE scenarios ADD COLUMN illustration_key TEXT NOT NULL DEFAULT 'retail';
ALTER TABLE scenarios ADD COLUMN illustration_alt TEXT NOT NULL DEFAULT 'Hai nhân vật đang trò chuyện';
ALTER TABLE scenarios ADD COLUMN partner_name TEXT NOT NULL DEFAULT 'Alex';
ALTER TABLE scenarios ADD COLUMN learner_name TEXT NOT NULL DEFAULT 'Minh';
CREATE TABLE dialogue_lines (
    dialogue_line_id SERIAL PRIMARY KEY,
    scenario_id INT NOT NULL REFERENCES scenarios(scenario_id) ON DELETE CASCADE,
    position INT NOT NULL CHECK (position > 0),
    speaker TEXT NOT NULL CHECK (speaker IN ('partner','learner')),
    english_text TEXT NOT NULL,
    vietnamese_text TEXT NOT NULL,
    UNIQUE(scenario_id, position)
);




