-- Keep guided practice prompts in sync with the two-character audio script.
UPDATE scenario_turns t SET bot_reaction_rules=p.english_text,
    expected_user_intent=l.english_text, suggested_sample_phrases=ARRAY[l.english_text]
FROM dialogue_lines p JOIN dialogue_lines l ON l.scenario_id=p.scenario_id AND l.position=p.position+1
WHERE t.scenario_id=p.scenario_id AND p.speaker='partner' AND t.step_order=(p.position+1)/2;
UPDATE scenarios s SET initial_ai_greeting=d.english_text FROM dialogue_lines d WHERE d.scenario_id=s.scenario_id AND d.position=1;

