INSERT INTO lessons (lesson_id,module_id,title,target_situation,order_index) VALUES
(110, 1, 'Tư vấn kích cỡ và màu sắc', 'Khách thử áo và chọn kích cỡ, màu sắc phù hợp.', 30),
(111, 1, 'Kiểm tra hàng tồn và đề xuất thay thế', 'Sản phẩm khách muốn đã hết hàng; nhân viên đề nghị lựa chọn khác.', 31),
(112, 1, 'Thỏa thuận giao hàng và thời gian nhận', 'Khách mua đồ và hỏi phí, địa chỉ, thời gian giao.', 32),
(113, 1, 'Giải thích bảo hành sản phẩm', 'Khách hỏi thời hạn bảo hành và cách yêu cầu hỗ trợ.', 33),
(114, 1, 'Tiếp nhận khiếu nại và xin lỗi khách', 'Nhân viên lắng nghe khách phàn nàn và đề xuất kiểm tra.', 34),
(115, 1, 'Tư vấn đơn hàng qua điện thoại', 'Xác nhận mã đơn và thông tin khi khách gọi hỏi.', 35),
(116, 1, 'Đặt lịch tư vấn và xác nhận cuộc hẹn', 'Thống nhất thời gian gặp khách và gửi xác nhận.', 36),
(117, 1, 'Hỗ trợ khách dùng mã ưu đãi', 'Khách mua trực tuyến gặp lỗi khi nhập mã giảm giá.', 37),
(215, 2, 'Tham quan Sagrada Família tại Barcelona', 'Du khách hỏi nhân viên về thời gian vào cửa và hướng dẫn âm thanh.', 38),
(216, 2, 'Hỏi đường đi bộ tại Vạn Lý Trường Thành', 'Du khách hỏi người hướng dẫn về đoạn đường dốc và nơi nghỉ.', 39),
(217, 2, 'Ngắm thác Niagara và hỏi khu vực an toàn', 'Du khách hỏi nhân viên điểm ngắm cảnh và lưu ý khi trời mưa.', 40),
(218, 2, 'Trò chuyện với người bản địa tại Central Park', 'Du khách tìm đường đi bộ và quán cà phê gần công viên.', 41),
(219, 2, 'Gọi cà phê và hỏi đồ uống địa phương', 'Khách hỏi nhân viên đồ uống đặc trưng và chọn mang đi.', 42),
(220, 2, 'Hỏi thành phần món ăn và báo dị ứng', 'Khách kiểm tra thành phần và nhờ nhân viên xác nhận với bếp.', 43),
(221, 2, 'Nhận phòng sớm và nhờ giữ hành lý', 'Khách đến khách sạn trước giờ nhận phòng và hỏi nơi gửi hành lý.', 44),
(222, 2, 'Nhờ giúp khi thất lạc đồ tại điểm tham quan', 'Du khách hỏi quầy thông tin và mô tả món đồ thất lạc.', 45);
