(22102, 221, 'Could you store my luggage until then?', 'Bạn có thể giữ hành lý của tôi đến lúc đó không?', '/kʊd ju stɔr maɪ ˈlʌɡɪdʒ ənˈtɪl ðɛn/', '', 'Khách đến khách sạn trước giờ nhận phòng và hỏi nơi gửi hành lý.'),
(22103, 221, 'What time should I come back?', 'Tôi nên quay lại lúc mấy giờ?', '/wʌt taɪm ʃʊd aɪ kʌm bæk/', '', 'Khách đến khách sạn trước giờ nhận phòng và hỏi nơi gửi hành lý.'),
(22104, 221, 'early check-in', 'nhận phòng sớm', '/ˈɜrli ˈtʃɛkˌɪn/', '', 'VOCABULARY'),
(22105, 221, 'luggage', 'hành lý', '/ˈlʌɡɪdʒ/', '', 'VOCABULARY'),
(22106, 221, 'storage', 'chỗ giữ đồ', '/ˈstɔrɪdʒ/', '', 'VOCABULARY'),
(22201, 222, 'Where is the lost and found desk?', 'Quầy đồ thất lạc ở đâu?', '/wɛr ɪz ðə lɔst ænd faʊnd dɛsk/', '', 'Du khách hỏi quầy thông tin và mô tả món đồ thất lạc.'),
(22202, 222, 'I lost a small black backpack.', 'Tôi làm mất một ba lô nhỏ màu đen.', '/aɪ lɔst ə smɔl blæk ˈbækˌpæk/', '', 'Du khách hỏi quầy thông tin và mô tả món đồ thất lạc.'),
(22203, 222, 'Could you help me fill out a report?', 'Bạn giúp tôi điền bản báo cáo được không?', '/kʊd ju hɛlp mi fɪl aʊt ə rɪˈpɔrt/', '', 'Du khách hỏi quầy thông tin và mô tả món đồ thất lạc.'),
(22204, 222, 'lost and found', 'quầy đồ thất lạc', '/lɔst ænd faʊnd/', '', 'VOCABULARY'),
(22205, 222, 'backpack', 'ba lô', '/ˈbækˌpæk/', '', 'VOCABULARY'),
(22206, 222, 'report', 'bản báo cáo', '/rɪˈpɔrt/', '', 'VOCABULARY');
INSERT INTO scenarios (scenario_id,lesson_id,title,ai_role_name,user_role_name,context_briefing,initial_ai_greeting,illustration_key,illustration_alt,partner_name,learner_name) VALUES
(519, 110, 'Tư vấn kích cỡ và màu sắc', 'Khách hàng', 'Nhân viên bán hàng', 'Khách thử áo và chọn kích cỡ, màu sắc phù hợp.', 'I would like to try this shirt.', 'retail', 'Khách thử áo và chọn kích cỡ, màu sắc phù hợp.', 'Emma', 'Minh'),
(520, 111, 'Kiểm tra hàng tồn và đề xuất thay thế', 'Khách hàng', 'Nhân viên bán hàng', 'Sản phẩm khách muốn đã hết hàng; nhân viên đề nghị lựa chọn khác.', 'Do you have this camera?', 'retail', 'Sản phẩm khách muốn đã hết hàng; nhân viên đề nghị lựa chọn khác.', 'Alex', 'Lan'),
(521, 112, 'Thỏa thuận giao hàng và thời gian nhận', 'Khách hàng', 'Nhân viên bán hàng', 'Khách mua đồ và hỏi phí, địa chỉ, thời gian giao.', 'Can you deliver this to my hotel?', 'retail', 'Khách mua đồ và hỏi phí, địa chỉ, thời gian giao.', 'Oliver', 'Minh'),
(522, 113, 'Giải thích bảo hành sản phẩm', 'Khách hàng', 'Nhân viên bán hàng', 'Khách hỏi thời hạn bảo hành và cách yêu cầu hỗ trợ.', 'Does this product have a warranty?', 'retail', 'Khách hỏi thời hạn bảo hành và cách yêu cầu hỗ trợ.', 'Sofia', 'Lan'),
(523, 114, 'Tiếp nhận khiếu nại và xin lỗi khách', 'Khách hàng', 'Nhân viên bán hàng', 'Nhân viên lắng nghe khách phàn nàn và đề xuất kiểm tra.', 'I received the wrong item yesterday.', 'retail', 'Nhân viên lắng nghe khách phàn nàn và đề xuất kiểm tra.', 'Daniel', 'Minh'),
(524, 115, 'Tư vấn đơn hàng qua điện thoại', 'Khách hàng', 'Nhân viên bán hàng', 'Xác nhận mã đơn và thông tin khi khách gọi hỏi.', 'Hello. I am calling about my order.', 'retail', 'Xác nhận mã đơn và thông tin khi khách gọi hỏi.', 'Grace', 'Lan'),
(525, 116, 'Đặt lịch tư vấn và xác nhận cuộc hẹn', 'Khách hàng', 'Nhân viên bán hàng', 'Thống nhất thời gian gặp khách và gửi xác nhận.', 'I would like to book a consultation.', 'retail', 'Thống nhất thời gian gặp khách và gửi xác nhận.', 'James', 'Minh'),
(526, 117, 'Hỗ trợ khách dùng mã ưu đãi', 'Khách hàng', 'Nhân viên bán hàng', 'Khách mua trực tuyến gặp lỗi khi nhập mã giảm giá.', 'Where do I enter my discount code?', 'retail', 'Khách mua trực tuyến gặp lỗi khi nhập mã giảm giá.', 'Mia', 'Lan'),
(527, 215, 'Tham quan Sagrada Família tại Barcelona', 'Nhân viên / người bản địa', 'Du khách', 'Du khách hỏi nhân viên về thời gian vào cửa và hướng dẫn âm thanh.', 'Welcome. Your ticket has a timed entry.', 'museum', 'Du khách hỏi nhân viên về thời gian vào cửa và hướng dẫn âm thanh.', 'Isabel', 'An'),
(528, 216, 'Hỏi đường đi bộ tại Vạn Lý Trường Thành', 'Nhân viên / người bản địa', 'Du khách', 'Du khách hỏi người hướng dẫn về đoạn đường dốc và nơi nghỉ.', 'Hello. Are you planning to walk this part of the wall?', 'city', 'Du khách hỏi người hướng dẫn về đoạn đường dốc và nơi nghỉ.', 'Li', 'An'),
(529, 217, 'Ngắm thác Niagara và hỏi khu vực an toàn', 'Nhân viên / người bản địa', 'Du khách', 'Du khách hỏi nhân viên điểm ngắm cảnh và lưu ý khi trời mưa.', 'Hello. Would you like directions to a viewpoint?', 'city', 'Du khách hỏi nhân viên điểm ngắm cảnh và lưu ý khi trời mưa.', 'Noah', 'An'),
(530, 218, 'Trò chuyện với người bản địa tại Central Park', 'Nhân viên / người bản địa', 'Du khách', 'Du khách tìm đường đi bộ và quán cà phê gần công viên.', 'Hi. Are you enjoying the park?', 'city', 'Du khách tìm đường đi bộ và quán cà phê gần công viên.', 'Ava', 'An'),
(531, 219, 'Gọi cà phê và hỏi đồ uống địa phương', 'Nhân viên / người bản địa', 'Du khách', 'Khách hỏi nhân viên đồ uống đặc trưng và chọn mang đi.', 'Welcome. What would you like to drink?', 'restaurant', 'Khách hỏi nhân viên đồ uống đặc trưng và chọn mang đi.', 'Ella', 'An'),
(532, 220, 'Hỏi thành phần món ăn và báo dị ứng', 'Nhân viên / người bản địa', 'Du khách', 'Khách kiểm tra thành phần và nhờ nhân viên xác nhận với bếp.', 'Would you like to order this dish?', 'restaurant', 'Khách kiểm tra thành phần và nhờ nhân viên xác nhận với bếp.', 'Leo', 'An'),
(533, 221, 'Nhận phòng sớm và nhờ giữ hành lý', 'Nhân viên / người bản địa', 'Du khách', 'Khách đến khách sạn trước giờ nhận phòng và hỏi nơi gửi hành lý.', 'Welcome. You have arrived before the usual check-in time.', 'hotel', 'Khách đến khách sạn trước giờ nhận phòng và hỏi nơi gửi hành lý.', 'Ruby', 'An'),
(534, 222, 'Nhờ giúp khi thất lạc đồ tại điểm tham quan', 'Nhân viên / người bản địa', 'Du khách', 'Du khách hỏi quầy thông tin và mô tả món đồ thất lạc.', 'Hello. Do you need assistance?', 'museum', 'Du khách hỏi quầy thông tin và mô tả món đồ thất lạc.', 'Henry', 'An');
INSERT INTO scenario_turns (scenario_id,step_order,expected_user_intent,bot_reaction_rules) VALUES
(519, 1, 'What size do you usually wear?', 'I would like to try this shirt.'),
(519, 2, 'Would you like to try a different colour?', 'Medium, please. Do you have it in blue?'),
(519, 3, 'The fitting room is over there.', 'Yes, blue would be great. Where can I try it?'),
(519, 4, 'Let me know if you need another size.', 'Thank you. I will try it on.'),
(520, 1, 'Let me check if it is in stock.', 'Do you have this camera?'),
(520, 2, 'This model is currently sold out.', 'Thank you. Is the black model available?'),
(520, 3, 'Would you like to see a similar model?', 'That is a pity. What else would you recommend?'),
(520, 4, 'This one has similar features.', 'Yes, please show me.'),
(521, 1, 'Could you confirm your delivery address?', 'Can you deliver this to my hotel?'),
(521, 2, 'Delivery usually takes three business days.', 'It is the City Hotel. How long does delivery take?'),
(521, 3, 'We will send you a tracking number.', 'How can I track the order?'),
(521, 4, 'Of course. Please confirm your email address.', 'Thank you. Please send it by email.'),
(522, 1, 'This product comes with a one-year warranty.', 'Does this product have a warranty?'),
(522, 2, 'Please keep the receipt as proof of purchase.', 'What documents should I keep?'),
(522, 3, 'Contact our support team if you need help.', 'Who should I contact if it stops working?'),
(522, 4, 'You are welcome. The contact details are on the receipt.', 'Thank you for explaining.'),
(523, 1, 'I am sorry for the inconvenience.', 'I received the wrong item yesterday.'),
(523, 2, 'Could you explain what happened?', 'I would like to report a problem with my order.'),
(523, 3, 'Let me find a solution for you.', 'I ordered a blue bag, but received a red one.'),
(523, 4, 'I will check whether we can arrange an exchange.', 'Thank you. I would prefer the blue bag.'),
(524, 1, 'Could I have your order number?', 'Hello. I am calling about my order.'),
(524, 2, 'Could you spell your name, please?', 'It is A102. My name is Grace.'),
(524, 3, 'Please hold while I check your order.', 'G-R-A-C-E. Can you check the delivery status?'),
(524, 4, 'Thank you for waiting. I have found your order.', 'Of course. I will wait.'),
(525, 1, 'What time would work best for you?', 'I would like to book a consultation.'),
(525, 2, 'We have an appointment available on Friday.', 'Friday morning would be good.'),
(525, 3, 'I will send you a confirmation email.', 'Great. Can you confirm it in writing?'),
(525, 4, 'We look forward to seeing you.', 'Thank you. I will check my email.'),
(526, 1, 'Please enter the code at checkout.', 'Where do I enter my discount code?'),
(526, 2, 'Let me check the expiry date.', 'I entered it, but it does not work.'),
(526, 3, 'This offer applies to selected items only.', 'The code is still valid. Why was it rejected?'),
(526, 4, 'Of course. I will send you the list.', 'I see. Could you show me which items are included?'),
(527, 1, 'Where should I wait for my entry time?', 'Welcome. Your ticket has a timed entry.'),
(527, 2, 'Is an audio guide available in English?', 'Please wait near this entrance. Do you need a guide?'),
(527, 3, 'Could you show me the visitor route?', 'You can check the available languages at the desk.'),
(527, 4, 'Thank you. I will follow the signs.', 'Yes, follow the signs along this route.'),
(528, 1, 'Is this section suitable for beginners?', 'Hello. Are you planning to walk this part of the wall?'),
(528, 2, 'Are there many steep steps?', 'Some parts can be challenging. How much walking do you prefer?'),
(528, 3, 'Where can we take a short break?', 'There are steps here, so take your time.'),
(528, 4, 'Thank you. We will take it slowly.', 'Please ask the staff for the nearest designated rest area.'),
(529, 1, 'Where is the nearest viewing area?', 'Hello. Would you like directions to a viewpoint?'),
(529, 2, 'Do I need a raincoat?', 'Follow the signs ahead. There can be spray from the falls.'),
(529, 3, 'Is this path safe to use today?', 'A raincoat may help. Please also check the path signs.'),
(529, 4, 'Thank you. I will be careful.', 'Please check the current notices; wet surfaces can be slippery.'),
(530, 1, 'Could you recommend a peaceful walking route?', 'Hi. Are you enjoying the park?'),
(530, 2, 'Is there a café nearby?', 'The paths by the lake are lovely.'),
(530, 3, 'How long is the walk from here?', 'There may be a café near the exit. Check your map.'),
(530, 4, 'Thank you. That would be helpful.', 'It depends on which exit you choose. I can show you on the map.'),
(531, 1, 'What local drink would you recommend?', 'Welcome. What would you like to drink?'),
(531, 2, 'Could I have it without sugar?', 'Our local coffee is popular. How would you like it?'),
(531, 3, 'To take away, please.', 'Of course. For here or to take away?'),
(531, 4, 'Thank you. Have a nice day!', 'Here you are. Enjoy your coffee!'),
(532, 1, 'Does this dish contain peanuts?', 'Would you like to order this dish?'),
(532, 2, 'I have a food allergy.', 'I am not sure. Do you have any dietary requirements?'),
(532, 3, 'Could you check with the kitchen, please?', 'Thank you for telling me. We need to confirm the ingredients.'),
(532, 4, 'Thank you. Please let me know before I order.', 'Of course. Please wait while I ask the chef.'),
(533, 1, 'Is early check-in possible?', 'Welcome. You have arrived before the usual check-in time.'),
(533, 2, 'Could you store my luggage until then?', 'Let me check. Your room is not ready yet.'),
(533, 3, 'What time should I come back?', 'We can check our luggage storage availability.'),
(533, 4, 'Thank you. Please let me know.', 'I will confirm the time after checking with housekeeping.'),
(534, 1, 'Where is the lost and found desk?', 'Hello. Do you need assistance?'),
(534, 2, 'I lost a small black backpack.', 'It is near the information desk. What did you lose?'),
(534, 3, 'Could you help me fill out a report?', 'We can check whether someone has handed it in.'),
(534, 4, 'Thank you. I last saw it near the entrance.', 'Certainly. Please describe where you last saw it.');
INSERT INTO dialogue_lines (scenario_id,position,speaker,english_text,vietnamese_text) VALUES
(501, 1, 'partner', 'Hello! I have an appointment here today.', 'Xin chào! Hôm nay tôi có lịch hẹn ở đây.'),
(501, 2, 'learner', 'Good morning! Welcome to our office.', 'Chào buổi sáng! Chào mừng anh đến văn phòng.'),
(501, 3, 'partner', 'Thank you. Where is the meeting room?', 'Cảm ơn. Phòng họp ở đâu?'),
(501, 4, 'learner', 'Please follow me to the meeting room.', 'Mời anh theo tôi đến phòng họp.'),
(501, 5, 'partner', 'Could I have some water, please?', 'Cho tôi xin chút nước nhé?'),
(501, 6, 'learner', 'Of course. Please take a seat.', 'Được ạ. Mời anh ngồi.'),
(501, 7, 'partner', 'Thank you for your help.', 'Cảm ơn bạn đã giúp đỡ.'),
(501, 8, 'learner', 'You are welcome.', 'Không có gì ạ.'),
(502, 1, 'partner', 'May I see your passport, please?', 'Cho tôi xem hộ chiếu nhé?'),
(502, 2, 'learner', 'Here is my passport.', 'Đây là hộ chiếu của tôi.'),
(502, 3, 'partner', 'What is the purpose of your visit?', 'Mục đích chuyến đi của bạn là gì?'),
(502, 4, 'learner', 'I am here for a vacation.', 'Tôi đến đây để du lịch.'),
(502, 5, 'partner', 'How long will you stay?', 'Bạn sẽ ở bao lâu?'),
(502, 6, 'learner', 'I will stay for five days.', 'Tôi sẽ ở trong năm ngày.'),
(502, 7, 'partner', 'Enjoy your trip!', 'Chúc bạn một chuyến đi vui vẻ!'),
(502, 8, 'learner', 'Thank you very much.', 'Cảm ơn rất nhiều.'),
(503, 1, 'partner', 'Hi! Are you ready to order?', 'Chào bạn! Bạn đã sẵn sàng gọi món chưa?'),
(503, 2, 'learner', 'Could I see the menu, please?', 'Cho tôi xem thực đơn nhé?'),
(503, 3, 'partner', 'Of course. Would you like something to drink?', 'Được chứ. Bạn muốn uống gì không?'),
(503, 4, 'learner', 'Water, please.', 'Cho tôi nước lọc nhé.'),
(503, 5, 'partner', 'Would you like to pay by cash or card?', 'Bạn muốn thanh toán tiền mặt hay thẻ?'),
(503, 6, 'learner', 'Can I pay by card?', 'Tôi thanh toán bằng thẻ được không?'),
(503, 7, 'partner', 'Certainly. Thank you and have a nice day!', 'Được chứ. Cảm ơn và chúc bạn một ngày tốt lành!'),
(503, 8, 'learner', 'Thank you. You too!', 'Cảm ơn. Bạn cũng vậy nhé!'),
(504, 1, 'partner', 'Hello. I would like to buy a gift.', 'Xin chào. Tôi muốn mua một món quà.'),
(504, 2, 'learner', 'Welcome! What are you looking for today?', 'Xin chào! Hôm nay anh/chị đang tìm sản phẩm gì?'),
(504, 3, 'partner', 'I am looking for something special.', 'Tôi đang tìm một món đặc biệt.'),
(504, 4, 'learner', 'Who is the gift for?', 'Món quà này dành cho ai?'),
(504, 5, 'partner', 'It is for my sister.', 'Món quà dành cho chị gái tôi.'),
(504, 6, 'learner', 'What is your budget?', 'Ngân sách của anh/chị là bao nhiêu?'),
(504, 7, 'partner', 'My budget is fifty dollars.', 'Ngân sách của tôi là năm mươi đô la.'),
(504, 8, 'learner', 'Thank you. Let me show you some options.', 'Cảm ơn. Để tôi cho anh/chị xem vài lựa chọn.'),
(505, 1, 'partner', 'What is this bag made of?', 'Chiếc túi này làm từ gì?'),
(505, 2, 'learner', 'This bag is made of recycled materials.', 'Chiếc túi này được làm từ vật liệu tái chế.'),
(505, 3, 'partner', 'Is it comfortable to carry?', 'Mang túi này có thoải mái không?'),
(505, 4, 'learner', 'It is lightweight and easy to carry.', 'Nó nhẹ và dễ mang theo.'),
(505, 5, 'partner', 'Can I try it?', 'Tôi có thể thử không?'),
(505, 6, 'learner', 'Would you like to try it?', 'Anh/chị có muốn thử không?'),
(505, 7, 'partner', 'Thank you. It feels comfortable.', 'Cảm ơn. Mang rất thoải mái.'),
(505, 8, 'learner', 'You are welcome. Take your time.', 'Không có gì. Anh/chị cứ từ từ xem.'),
(506, 1, 'partner', 'How much is this item?', 'Món này giá bao nhiêu?'),
(506, 2, 'learner', 'The price is thirty dollars.', 'Giá là ba mươi đô la.'),
(506, 3, 'partner', 'Does that include tax?', 'Giá đã bao gồm thuế chưa?'),
(506, 4, 'learner', 'This price includes tax.', 'Giá này đã bao gồm thuế.'),
(506, 5, 'partner', 'Can you offer a discount?', 'Bạn có thể giảm giá không?'),
(506, 6, 'learner', 'We can offer a ten percent discount.', 'Chúng tôi có thể giảm giá mười phần trăm.'),
(506, 7, 'partner', 'That sounds good.', 'Nghe hợp lý đấy.'),
(506, 8, 'learner', 'Would you like to purchase it?', 'Anh/chị có muốn mua không?'),
(507, 1, 'partner', 'I would like to buy this one.', 'Tôi muốn mua món này.'),
(507, 2, 'learner', 'Would you like one or two?', 'Anh/chị muốn mua một hay hai chiếc?'),
(507, 3, 'partner', 'Just one, please.', 'Một chiếc thôi nhé.'),
(507, 4, 'learner', 'How would you like to pay?', 'Anh/chị muốn thanh toán bằng cách nào?'),
(507, 5, 'partner', 'I will pay by card.', 'Tôi sẽ thanh toán bằng thẻ.'),
(507, 6, 'learner', 'Here is your receipt.', 'Đây là biên lai của anh/chị.'),
(507, 7, 'partner', 'Thank you for your help.', 'Cảm ơn bạn đã giúp đỡ.'),
(507, 8, 'learner', 'You are welcome. Have a nice day!', 'Không có gì. Chúc anh/chị một ngày tốt lành!'),
(508, 1, 'partner', 'I would like to return this bag.', 'Tôi muốn trả lại chiếc túi này.'),
(508, 2, 'learner', 'May I see your receipt?', 'Tôi có thể xem biên lai của anh/chị không?'),
(508, 3, 'partner', 'Yes, here is my receipt.', 'Có, đây là biên lai của tôi.'),
(508, 4, 'learner', 'Would you prefer an exchange or a refund?', 'Anh/chị muốn đổi hàng hay hoàn tiền?'),
(508, 5, 'partner', 'I would prefer a refund.', 'Tôi muốn được hoàn tiền.'),
(508, 6, 'learner', 'Let me check our return policy.', 'Để tôi kiểm tra chính sách đổi trả của cửa hàng.'),
(508, 7, 'partner', 'Can you tell me if that is possible?', 'Bạn cho tôi biết có được không nhé?'),
(508, 8, 'learner', 'I will check the policy and explain your options.', 'Tôi sẽ kiểm tra chính sách và giải thích các lựa chọn.'),
(509, 1, 'partner', 'Hello. Do you need directions?', 'Xin chào. Bạn cần chỉ đường không?'),
(509, 2, 'learner', 'Excuse me, how do I get to the Eiffel Tower?', 'Xin lỗi, tôi đi đến tháp Eiffel bằng cách nào?'),
(509, 3, 'partner', 'Are you travelling by metro?', 'Bạn đi bằng tàu điện ngầm phải không?'),
(509, 4, 'learner', 'Which metro station should I use?', 'Tôi nên đi đến ga tàu điện ngầm nào?'),
(509, 5, 'partner', 'Would you like to walk from the station?', 'Bạn có muốn đi bộ từ nhà ga không?'),
(509, 6, 'learner', 'Is it within walking distance?', 'Có thể đi bộ đến đó không?'),
(509, 7, 'partner', 'You can check the route on your map.', 'Bạn có thể xem đường đi trên bản đồ.'),
(509, 8, 'learner', 'Thank you for your help.', 'Cảm ơn bạn đã giúp đỡ.'),
(510, 1, 'partner', 'Welcome to the Louvre. How can I help?', 'Chào mừng đến Louvre. Tôi có thể giúp gì?'),
(510, 2, 'learner', 'Do I need to book a ticket in advance?', 'Tôi có cần đặt vé trước không?'),
(510, 3, 'partner', 'Have you already purchased a ticket?', 'Bạn đã mua vé chưa?'),
(510, 4, 'learner', 'Where is the entrance for ticket holders?', 'Lối vào dành cho người đã có vé ở đâu?'),
(510, 5, 'partner', 'Do you have any questions about the museum rules?', 'Bạn có câu hỏi gì về quy định bảo tàng không?'),
(510, 6, 'learner', 'Is photography allowed here?', 'Ở đây có được phép chụp ảnh không?'),
(510, 7, 'partner', 'Please check the signs in each gallery.', 'Hãy xem biển hướng dẫn trong từng phòng trưng bày.'),
(510, 8, 'learner', 'Thank you. I will follow the rules.', 'Cảm ơn. Tôi sẽ tuân thủ quy định.'),
(511, 1, 'partner', 'Welcome. Would you like information about our tours?', 'Xin chào. Bạn muốn tìm hiểu về các tour không?'),
(511, 2, 'learner', 'Is there a guided tour in English?', 'Có tour có hướng dẫn bằng tiếng Anh không?'),
(511, 3, 'partner', 'Do you have any questions before booking?', 'Bạn có câu hỏi nào trước khi đặt tour không?'),
(511, 4, 'learner', 'How long does the tour take?', 'Tour kéo dài bao lâu?'),
(511, 5, 'partner', 'What would you like to learn about the Colosseum?', 'Bạn muốn tìm hiểu gì về Colosseum?'),
(511, 6, 'learner', 'Could you tell me about the history of this place?', 'Bạn có thể kể cho tôi về lịch sử nơi này không?'),
(511, 7, 'partner', 'Our guide will explain the history during the tour.', 'Hướng dẫn viên sẽ giải thích lịch sử trong tour.'),
(511, 8, 'learner', 'Thank you. That sounds interesting.', 'Cảm ơn. Nghe rất thú vị.'),
(512, 1, 'partner', 'Welcome. Is this your first visit?', 'Xin chào. Đây là lần đầu bạn đến phải không?'),
(512, 2, 'learner', 'Are there any rules I should follow?', 'Có quy tắc nào tôi cần tuân thủ không?'),
(512, 3, 'partner', 'Are you entering this building?', 'Bạn có định vào tòa nhà này không?'),
(512, 4, 'learner', 'Should I take off my shoes here?', 'Tôi có nên cởi giày ở đây không?'),
(512, 5, 'partner', 'Do you have a question about photography?', 'Bạn có câu hỏi về việc chụp ảnh không?'),
(512, 6, 'learner', 'May I take a photo of this area?', 'Tôi có thể chụp ảnh khu vực này không?'),
(512, 7, 'partner', 'Please look for signs before taking photos.', 'Hãy xem biển báo trước khi chụp ảnh.'),
(512, 8, 'learner', 'Thank you. I will be respectful.', 'Cảm ơn. Tôi sẽ ứng xử lịch sự.'),
(513, 1, 'partner', 'Hello. Are you looking for a place to take photos?', 'Xin chào. Bạn đang tìm nơi chụp ảnh phải không?'),
(513, 2, 'learner', 'Could you recommend a good viewpoint?', 'Bạn có thể gợi ý một điểm ngắm cảnh đẹp không?'),
(513, 3, 'partner', 'This spot has a nice view.', 'Chỗ này có cảnh đẹp.'),
(513, 4, 'learner', 'Would you mind taking a photo of us?', 'Bạn có phiền chụp giúp chúng tôi một bức ảnh không?'),
(513, 5, 'partner', 'How would you like me to frame the photo?', 'Bạn muốn tôi lấy khung hình như thế nào?'),
(513, 6, 'learner', 'Could you include the landmark in the background?', 'Bạn có thể lấy địa danh vào hậu cảnh không?'),
(513, 7, 'partner', 'Here is your phone. I hope you like the photo.', 'Điện thoại của bạn đây. Hy vọng bạn thích ảnh.'),
(513, 8, 'learner', 'Thank you so much for your help.', 'Cảm ơn bạn rất nhiều.'),
(514, 1, 'partner', 'Welcome. What kind of gift would you like?', 'Xin chào. Bạn muốn mua loại quà nào?'),
(514, 2, 'learner', 'I am looking for a small gift for my family.', 'Tôi đang tìm một món quà nhỏ cho gia đình.'),
(514, 3, 'partner', 'Would you like to know where this item was made?', 'Bạn có muốn biết món này được làm ở đâu không?'),
(514, 4, 'learner', 'Is this made locally?', 'Món này có được làm tại địa phương không?'),
(514, 5, 'partner', 'Do you have a question about the pattern?', 'Bạn có câu hỏi về họa tiết không?'),
(514, 6, 'learner', 'What does this design mean?', 'Họa tiết này có ý nghĩa gì?'),
(514, 7, 'partner', 'I can explain its meaning and show you other designs.', 'Tôi có thể giải thích ý nghĩa và cho bạn xem các mẫu khác.'),
(514, 8, 'learner', 'Thank you. I would like to see the other designs.', 'Cảm ơn. Tôi muốn xem các mẫu khác.'),
(515, 1, 'partner', 'Hello. Are you interested in this cup?', 'Xin chào. Bạn thích chiếc cốc này phải không?'),
(515, 2, 'learner', 'Is this handmade?', 'Món này có được làm thủ công không?'),
(515, 3, 'partner', 'Would you like to know about the material?', 'Bạn muốn tìm hiểu về chất liệu không?'),
(515, 4, 'learner', 'What is it made of?', 'Nó được làm từ chất liệu gì?'),
(515, 5, 'partner', 'Do you need advice on caring for it?', 'Bạn cần lời khuyên về cách bảo quản không?'),
(515, 6, 'learner', 'How should I take care of it?', 'Tôi nên bảo quản nó như thế nào?'),
(515, 7, 'partner', 'I can give you the care instructions.', 'Tôi có thể đưa bạn hướng dẫn bảo quản.'),
(515, 8, 'learner', 'Yes, please. Thank you.', 'Có nhé. Cảm ơn.'),
(516, 1, 'partner', 'Hello. Do you like this magnet?', 'Xin chào. Bạn thích nam châm này phải không?'),
(516, 2, 'learner', 'How much is this magnet?', 'Nam châm lưu niệm này giá bao nhiêu?'),
(516, 3, 'partner', 'It costs five dollars.', 'Món này giá năm đô la.'),
(516, 4, 'learner', 'Is the price fixed?', 'Giá có cố định không?'),
(516, 5, 'partner', 'We may have a discount for multiple items.', 'Mua nhiều món có thể được giảm giá.'),
(516, 6, 'learner', 'Could you offer a discount if I buy two?', 'Bạn có thể giảm giá nếu tôi mua hai chiếc không?'),
(516, 7, 'partner', 'Let me check the price for two.', 'Để tôi kiểm tra giá cho hai chiếc.'),
(516, 8, 'learner', 'Thank you. Please let me know the total.', 'Cảm ơn. Bạn báo tổng tiền giúp tôi nhé.'),
(517, 1, 'partner', 'How would you like to pay?', 'Bạn muốn thanh toán bằng cách nào?'),
(517, 2, 'learner', 'Can I pay in the local currency?', 'Tôi có thể thanh toán bằng tiền địa phương không?'),
(517, 3, 'partner', 'Would you prefer to use a card?', 'Bạn muốn dùng thẻ không?'),
(517, 4, 'learner', 'Do you accept credit cards?', 'Cửa hàng có nhận thẻ tín dụng không?'),
(517, 5, 'partner', 'Here is your change. Is everything correct?', 'Đây là tiền thừa của bạn. Mọi thứ đã đúng chưa?'),
(517, 6, 'learner', 'Could you check my change, please?', 'Bạn có thể kiểm tra lại tiền thừa của tôi không?'),
(517, 7, 'partner', 'Of course. Let me count it again.', 'Được chứ. Để tôi đếm lại.'),
(517, 8, 'learner', 'Thank you for checking.', 'Cảm ơn đã kiểm tra.'),
(518, 1, 'partner', 'Would you like this wrapped?', 'Bạn có muốn gói món này không?'),
(518, 2, 'learner', 'Could you gift-wrap this, please?', 'Bạn có thể gói món này thành quà giúp tôi không?'),
(518, 3, 'partner', 'Are you taking it on a long journey?', 'Bạn sẽ mang nó đi xa phải không?'),
(518, 4, 'learner', 'Please pack it carefully. It is fragile.', 'Vui lòng đóng gói cẩn thận. Món này dễ vỡ.'),
(518, 5, 'partner', 'Would you like to inspect it first?', 'Bạn muốn kiểm tra món đồ trước không?'),
(518, 6, 'learner', 'Can I check the item before you wrap it?', 'Tôi có thể kiểm tra món đồ trước khi bạn gói không?'),
(518, 7, 'partner', 'Of course. I will wrap it after you check it.', 'Được chứ. Tôi sẽ gói sau khi bạn kiểm tra.'),
(518, 8, 'learner', 'Thank you. That would be helpful.', 'Cảm ơn. Như vậy rất hữu ích.'),
(519, 1, 'partner', 'I would like to try this shirt.', 'Tôi muốn thử chiếc áo này.'),
(519, 2, 'learner', 'What size do you usually wear?', 'Anh/chị thường mặc cỡ nào?'),
(519, 3, 'partner', 'Medium, please. Do you have it in blue?', 'Cỡ vừa nhé. Có màu xanh không?'),
(519, 4, 'learner', 'Would you like to try a different colour?', 'Anh/chị có muốn thử màu khác không?'),
(519, 5, 'partner', 'Yes, blue would be great. Where can I try it?', 'Có, màu xanh rất hợp. Tôi thử ở đâu?'),
(519, 6, 'learner', 'The fitting room is over there.', 'Phòng thử đồ ở phía bên kia.'),
(519, 7, 'partner', 'Thank you. I will try it on.', 'Cảm ơn. Tôi sẽ thử.'),
(519, 8, 'learner', 'Let me know if you need another size.', 'Hãy cho tôi biết nếu anh/chị cần cỡ khác.'),
(520, 1, 'partner', 'Do you have this camera?', 'Bạn có máy ảnh này không?'),
(520, 2, 'learner', 'Let me check if it is in stock.', 'Để tôi kiểm tra xem còn hàng không.'),
(520, 3, 'partner', 'Thank you. Is the black model available?', 'Cảm ơn. Mẫu màu đen còn không?'),
(520, 4, 'learner', 'This model is currently sold out.', 'Mẫu này hiện đã hết hàng.'),
(520, 5, 'partner', 'That is a pity. What else would you recommend?', 'Tiếc quá. Bạn gợi ý mẫu nào khác?'),
(520, 6, 'learner', 'Would you like to see a similar model?', 'Anh/chị muốn xem mẫu tương tự không?'),
(520, 7, 'partner', 'Yes, please show me.', 'Có, cho tôi xem nhé.'),
(520, 8, 'learner', 'This one has similar features.', 'Mẫu này có tính năng tương tự.'),
(521, 1, 'partner', 'Can you deliver this to my hotel?', 'Bạn có thể giao món này tới khách sạn không?'),
(521, 2, 'learner', 'Could you confirm your delivery address?', 'Anh/chị có thể xác nhận địa chỉ giao hàng không?'),
(521, 3, 'partner', 'It is the City Hotel. How long does delivery take?', 'Là khách sạn City. Giao hàng mất bao lâu?'),
(521, 4, 'learner', 'Delivery usually takes three business days.', 'Giao hàng thường mất ba ngày làm việc.'),
(521, 5, 'partner', 'How can I track the order?', 'Tôi theo dõi đơn hàng bằng cách nào?'),
(521, 6, 'learner', 'We will send you a tracking number.', 'Chúng tôi sẽ gửi mã theo dõi đơn hàng.'),
(521, 7, 'partner', 'Thank you. Please send it by email.', 'Cảm ơn. Vui lòng gửi qua email.'),
(521, 8, 'learner', 'Of course. Please confirm your email address.', 'Được ạ. Vui lòng xác nhận địa chỉ email.'),
(522, 1, 'partner', 'Does this product have a warranty?', 'Sản phẩm này có bảo hành không?'),
(522, 2, 'learner', 'This product comes with a one-year warranty.', 'Sản phẩm này được bảo hành một năm.'),
(522, 3, 'partner', 'What documents should I keep?', 'Tôi nên giữ giấy tờ nào?'),
(522, 4, 'learner', 'Please keep the receipt as proof of purchase.', 'Vui lòng giữ biên lai làm bằng chứng mua hàng.'),
(522, 5, 'partner', 'Who should I contact if it stops working?', 'Tôi liên hệ ai nếu sản phẩm không hoạt động?'),
(522, 6, 'learner', 'Contact our support team if you need help.', 'Hãy liên hệ bộ phận hỗ trợ nếu cần giúp đỡ.'),
(522, 7, 'partner', 'Thank you for explaining.', 'Cảm ơn bạn đã giải thích.'),
(522, 8, 'learner', 'You are welcome. The contact details are on the receipt.', 'Không có gì. Thông tin liên hệ nằm trên biên lai.'),
(523, 1, 'partner', 'I received the wrong item yesterday.', 'Hôm qua tôi nhận nhầm món hàng.'),
(523, 2, 'learner', 'I am sorry for the inconvenience.', 'Tôi xin lỗi vì sự bất tiện này.'),
(523, 3, 'partner', 'I would like to report a problem with my order.', 'Tôi muốn báo vấn đề với đơn hàng.'),
(523, 4, 'learner', 'Could you explain what happened?', 'Anh/chị có thể giải thích chuyện gì đã xảy ra không?'),
(523, 5, 'partner', 'I ordered a blue bag, but received a red one.', 'Tôi đặt túi xanh nhưng nhận túi đỏ.'),
(523, 6, 'learner', 'Let me find a solution for you.', 'Để tôi tìm giải pháp cho anh/chị.'),
(523, 7, 'partner', 'Thank you. I would prefer the blue bag.', 'Cảm ơn. Tôi muốn chiếc túi xanh.'),
(523, 8, 'learner', 'I will check whether we can arrange an exchange.', 'Tôi sẽ kiểm tra xem có thể sắp xếp đổi hàng không.'),
(524, 1, 'partner', 'Hello. I am calling about my order.', 'Xin chào. Tôi gọi để hỏi về đơn hàng.'),
(524, 2, 'learner', 'Could I have your order number?', 'Anh/chị cho tôi xin mã đơn hàng được không?'),
(524, 3, 'partner', 'It is A102. My name is Grace.', 'Mã là A102. Tôi tên Grace.'),
(524, 4, 'learner', 'Could you spell your name, please?', 'Anh/chị có thể đánh vần tên không?'),
(524, 5, 'partner', 'G-R-A-C-E. Can you check the delivery status?', 'G-R-A-C-E. Bạn kiểm tra trạng thái giao giúp tôi nhé?'),
(524, 6, 'learner', 'Please hold while I check your order.', 'Vui lòng chờ trong lúc tôi kiểm tra đơn hàng.'),
(524, 7, 'partner', 'Of course. I will wait.', 'Được. Tôi sẽ chờ.'),
(524, 8, 'learner', 'Thank you for waiting. I have found your order.', 'Cảm ơn đã chờ. Tôi đã tìm thấy đơn hàng.'),
(525, 1, 'partner', 'I would like to book a consultation.', 'Tôi muốn đặt lịch tư vấn.'),
(525, 2, 'learner', 'What time would work best for you?', 'Thời gian nào phù hợp nhất với anh/chị?'),
(525, 3, 'partner', 'Friday morning would be good.', 'Sáng thứ Sáu thì phù hợp.'),
(525, 4, 'learner', 'We have an appointment available on Friday.', 'Chúng tôi còn lịch hẹn vào thứ Sáu.'),
(525, 5, 'partner', 'Great. Can you confirm it in writing?', 'Tốt. Bạn xác nhận bằng văn bản được không?'),
(525, 6, 'learner', 'I will send you a confirmation email.', 'Tôi sẽ gửi email xác nhận cho anh/chị.'),
(525, 7, 'partner', 'Thank you. I will check my email.', 'Cảm ơn. Tôi sẽ kiểm tra email.'),
(525, 8, 'learner', 'We look forward to seeing you.', 'Chúng tôi mong được gặp anh/chị.'),
(526, 1, 'partner', 'Where do I enter my discount code?', 'Tôi nhập mã giảm giá ở đâu?'),
(526, 2, 'learner', 'Please enter the code at checkout.', 'Vui lòng nhập mã tại bước thanh toán.'),
(526, 3, 'partner', 'I entered it, but it does not work.', 'Tôi nhập rồi nhưng mã không hoạt động.'),
(526, 4, 'learner', 'Let me check the expiry date.', 'Để tôi kiểm tra ngày hết hạn.'),
(526, 5, 'partner', 'The code is still valid. Why was it rejected?', 'Mã vẫn còn hạn. Vì sao bị từ chối?'),
(526, 6, 'learner', 'This offer applies to selected items only.', 'Ưu đãi này chỉ áp dụng cho một số sản phẩm.'),
(526, 7, 'partner', 'I see. Could you show me which items are included?', 'Tôi hiểu. Bạn chỉ cho tôi những món được áp dụng nhé?'),
(526, 8, 'learner', 'Of course. I will send you the list.', 'Được ạ. Tôi sẽ gửi danh sách.'),
(527, 1, 'partner', 'Welcome. Your ticket has a timed entry.', 'Xin chào. Vé của bạn có giờ vào cửa cụ thể.'),
(527, 2, 'learner', 'Where should I wait for my entry time?', 'Tôi nên chờ giờ vào cửa ở đâu?'),
(527, 3, 'partner', 'Please wait near this entrance. Do you need a guide?', 'Bạn chờ gần lối vào này nhé. Bạn cần hướng dẫn không?'),
(527, 4, 'learner', 'Is an audio guide available in English?', 'Có hướng dẫn âm thanh bằng tiếng Anh không?'),
(527, 5, 'partner', 'You can check the available languages at the desk.', 'Bạn có thể hỏi các ngôn ngữ được hỗ trợ tại quầy.'),
(527, 6, 'learner', 'Could you show me the visitor route?', 'Bạn chỉ giúp tôi tuyến tham quan được không?'),
(527, 7, 'partner', 'Yes, follow the signs along this route.', 'Có, hãy đi theo biển chỉ dẫn dọc tuyến này.'),
(527, 8, 'learner', 'Thank you. I will follow the signs.', 'Cảm ơn. Tôi sẽ đi theo biển chỉ dẫn.'),
(528, 1, 'partner', 'Hello. Are you planning to walk this part of the wall?', 'Xin chào. Bạn định đi bộ đoạn tường này à?'),
(528, 2, 'learner', 'Is this section suitable for beginners?', 'Đoạn này có phù hợp với người mới không?'),
(528, 3, 'partner', 'Some parts can be challenging. How much walking do you prefer?', 'Một số đoạn khá khó đi. Bạn muốn đi bộ nhiều không?'),
(528, 4, 'learner', 'Are there many steep steps?', 'Có nhiều bậc thang dốc không?'),
(528, 5, 'partner', 'There are steps here, so take your time.', 'Ở đây có các bậc thang, hãy đi từ từ.'),
(528, 6, 'learner', 'Where can we take a short break?', 'Chúng tôi có thể nghỉ một chút ở đâu?'),
(528, 7, 'partner', 'Please ask the staff for the nearest designated rest area.', 'Bạn hỏi nhân viên về khu nghỉ được quy định gần nhất nhé.'),
(528, 8, 'learner', 'Thank you. We will take it slowly.', 'Cảm ơn. Chúng tôi sẽ đi chậm.'),
(529, 1, 'partner', 'Hello. Would you like directions to a viewpoint?', 'Xin chào. Bạn muốn hỏi đường tới điểm ngắm cảnh không?'),
(529, 2, 'learner', 'Where is the nearest viewing area?', 'Khu ngắm cảnh gần nhất ở đâu?'),
(529, 3, 'partner', 'Follow the signs ahead. There can be spray from the falls.', 'Hãy theo biển chỉ dẫn phía trước. Có thể có hơi nước bắn từ thác.'),
(529, 4, 'learner', 'Do I need a raincoat?', 'Tôi có cần áo mưa không?'),
(529, 5, 'partner', 'A raincoat may help. Please also check the path signs.', 'Áo mưa có thể hữu ích. Bạn cũng kiểm tra biển báo lối đi nhé.'),
(529, 6, 'learner', 'Is this path safe to use today?', 'Hôm nay lối đi này có an toàn không?'),
(529, 7, 'partner', 'Please check the current notices; wet surfaces can be slippery.', 'Vui lòng xem thông báo hiện tại; bề mặt ướt có thể trơn trượt.'),
(529, 8, 'learner', 'Thank you. I will be careful.', 'Cảm ơn. Tôi sẽ cẩn thận.'),
(530, 1, 'partner', 'Hi. Are you enjoying the park?', 'Chào bạn. Bạn thấy công viên thế nào?'),
(530, 2, 'learner', 'Could you recommend a peaceful walking route?', 'Bạn gợi ý tuyến đi bộ yên tĩnh được không?'),
(530, 3, 'partner', 'The paths by the lake are lovely.', 'Những lối đi cạnh hồ rất đẹp.'),
(530, 4, 'learner', 'Is there a café nearby?', 'Có quán cà phê gần đây không?'),
(530, 5, 'partner', 'There may be a café near the exit. Check your map.', 'Có thể có quán cà phê gần lối ra. Bạn xem bản đồ nhé.'),
(530, 6, 'learner', 'How long is the walk from here?', 'Đi bộ từ đây mất bao lâu?'),
(530, 7, 'partner', 'It depends on which exit you choose. I can show you on the map.', 'Còn tùy lối ra bạn chọn. Tôi có thể chỉ trên bản đồ.'),
(530, 8, 'learner', 'Thank you. That would be helpful.', 'Cảm ơn. Như vậy rất hữu ích.'),
(531, 1, 'partner', 'Welcome. What would you like to drink?', 'Xin chào. Bạn muốn uống gì?'),
(531, 2, 'learner', 'What local drink would you recommend?', 'Bạn gợi ý đồ uống địa phương nào?'),
(531, 3, 'partner', 'Our local coffee is popular. How would you like it?', 'Cà phê địa phương của chúng tôi rất được ưa chuộng. Bạn muốn dùng thế nào?'),
(531, 4, 'learner', 'Could I have it without sugar?', 'Tôi có thể gọi món đó không đường không?'),
(531, 5, 'partner', 'Of course. For here or to take away?', 'Được nhé. Bạn dùng tại chỗ hay mang đi?'),
(531, 6, 'learner', 'To take away, please.', 'Cho tôi mang đi nhé.'),
(531, 7, 'partner', 'Here you are. Enjoy your coffee!', 'Của bạn đây. Chúc bạn uống ngon miệng!'),
(531, 8, 'learner', 'Thank you. Have a nice day!', 'Cảm ơn. Chúc bạn một ngày tốt lành!'),
(532, 1, 'partner', 'Would you like to order this dish?', 'Bạn muốn gọi món này không?'),
(532, 2, 'learner', 'Does this dish contain peanuts?', 'Món này có chứa đậu phộng không?'),
(532, 3, 'partner', 'I am not sure. Do you have any dietary requirements?', 'Tôi chưa chắc. Bạn có yêu cầu đặc biệt về ăn uống không?'),
(532, 4, 'learner', 'I have a food allergy.', 'Tôi bị dị ứng thực phẩm.'),
(532, 5, 'partner', 'Thank you for telling me. We need to confirm the ingredients.', 'Cảm ơn đã cho biết. Chúng tôi cần xác nhận thành phần.'),
(532, 6, 'learner', 'Could you check with the kitchen, please?', 'Bạn kiểm tra lại với bếp giúp tôi nhé?'),
(532, 7, 'partner', 'Of course. Please wait while I ask the chef.', 'Được nhé. Bạn chờ tôi hỏi đầu bếp.'),
(532, 8, 'learner', 'Thank you. Please let me know before I order.', 'Cảm ơn. Vui lòng cho tôi biết trước khi tôi gọi món.'),
(533, 1, 'partner', 'Welcome. You have arrived before the usual check-in time.', 'Xin chào. Bạn đã đến trước giờ nhận phòng thông thường.'),
(533, 2, 'learner', 'Is early check-in possible?', 'Tôi có thể nhận phòng sớm không?'),
(533, 3, 'partner', 'Let me check. Your room is not ready yet.', 'Để tôi kiểm tra. Phòng của bạn chưa sẵn sàng.'),
(533, 4, 'learner', 'Could you store my luggage until then?', 'Bạn có thể giữ hành lý của tôi đến lúc đó không?'),
(533, 5, 'partner', 'We can check our luggage storage availability.', 'Chúng tôi có thể kiểm tra chỗ giữ hành lý còn trống.'),
(533, 6, 'learner', 'What time should I come back?', 'Tôi nên quay lại lúc mấy giờ?'),
(533, 7, 'partner', 'I will confirm the time after checking with housekeeping.', 'Tôi sẽ xác nhận giờ sau khi hỏi bộ phận buồng phòng.'),
(533, 8, 'learner', 'Thank you. Please let me know.', 'Cảm ơn. Vui lòng báo cho tôi nhé.'),
(534, 1, 'partner', 'Hello. Do you need assistance?', 'Xin chào. Bạn cần giúp đỡ không?'),
(534, 2, 'learner', 'Where is the lost and found desk?', 'Quầy đồ thất lạc ở đâu?'),
(534, 3, 'partner', 'It is near the information desk. What did you lose?', 'Quầy ở gần bàn thông tin. Bạn mất món gì?'),
(534, 4, 'learner', 'I lost a small black backpack.', 'Tôi làm mất một ba lô nhỏ màu đen.'),
(534, 5, 'partner', 'We can check whether someone has handed it in.', 'Chúng tôi có thể kiểm tra xem có ai đã giao nộp nó không.'),
(534, 6, 'learner', 'Could you help me fill out a report?', 'Bạn giúp tôi điền bản báo cáo được không?'),
(534, 7, 'partner', 'Certainly. Please describe where you last saw it.', 'Được chứ. Hãy mô tả nơi cuối cùng bạn nhìn thấy nó.'),
(534, 8, 'learner', 'Thank you. I last saw it near the entrance.', 'Cảm ơn. Lần cuối tôi thấy nó ở gần lối vào.');
